import json,os,subprocess as s,sys,tempfile
t=os.path.join(tempfile.mkdtemp(),'c.sqlite')
def run(h,*code):
    a=[sys.executable,'_tools/coord.py','dedup','where is pack defined and who calls it','--store',t,'--holder',h]
    for c in code:a+=['--code',c]
    p=s.run(a,capture_output=True,text=True,timeout=300);print(h,p.returncode,p.stdout[-500:],p.stderr[-300:])
    try:
        return json.loads(p.stdout)
    except ValueError:
        return {}
a=run('chk-a','it-ops-kb:_tools/rag.py#pack');b=run('chk-b','it-ops-kb:_tools/rag.py#pack')
ca=a.get('claimed') or []
ok=any('_tools/rag.py' in k for k in ca) and any(k.startswith('research:') for k in ca) and 'chk-a' in json.dumps(b.get('overlaps')) and not any('_tools/rag.py' in k for k in b.get('claimed') or [])
sys.exit(0 if ok else 1)

